def find_rectangular_frame(rows, color):
    frames = []
    for r in range(len(rows)):
        for c in range(len(rows[0])):
            if rows[r][c] == color:
                frame = None
                # Check if this is a corner (top-left, top-right, bottom-left, bottom-right)
